package com.steadyme.app.ui; import android.view.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.steadyme.app.databinding.ItemMoodLogBinding;import com.steadyme.app.model.MoodLog;import java.text.DateFormat;import java.util.*;
public class MoodLogAdapter extends RecyclerView.Adapter<MoodLogAdapter.Holder>{private final List<MoodLog> items=new ArrayList<>();public void submit(List<MoodLog> logs){items.clear();items.addAll(logs);notifyDataSetChanged();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int v){return new Holder(ItemMoodLogBinding.inflate(LayoutInflater.from(p.getContext()),p,false));}public void onBindViewHolder(@NonNull Holder h,int p){h.bind(items.get(p));}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{private final ItemMoodLogBinding b;Holder(ItemMoodLogBinding b){super(b.getRoot());this.b=b;}void bind(MoodLog l){b.tvEmotion.setText(l.getEmotion());b.tvMoodEmoji.setText(emoji(l.getEmotion()));b.tvNotes.setText(l.getNotes()==null||l.getNotes().isEmpty()?"No notes added":l.getNotes());b.tvDate.setText(l.getCreatedAt()==null?"Saving…":DateFormat.getDateInstance(DateFormat.MEDIUM).format(l.getCreatedAt().toDate()));}private String emoji(String e){if(e==null)return "🙂";switch(e){case "Happy":return "😊";case "Calm":return "😌";case "Elated":return "🤩";case "Anxious":return "😰";case "Sad":return "😢";case "Tired":return "😴";case "Angry":return "😠";default:return "😣";}}}}
